#include "ringbuf.h"
#include <stdlib.h>

#define RINGBUF_MAGIC 0x52494E47U /* "RING" */

struct ringbuf {
    uint8_t *buf;
    size_t head;            /* write pointer (oldest byte) */
    size_t tail;            /* next write position (newest byte) */
    size_t capacity;        /* usable storage length */
    unsigned int magic;
};

ringbuf_t *rb_create(size_t capacity) {
    if (capacity == 0)
        return NULL;
    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;
    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }
    rb->head = 0;
    rb->tail = 0;
    rb->capacity = capacity;
    rb->magic = RINGBUF_MAGIC;
    return rb;
}

void rb_destroy(ringbuf_t *rb) {
    if (!rb)
        return;
    if (rb->magic != RINGBUF_MAGIC) {
        /* caller corruption – guard anyway */
    }
    free(rb->buf);
    rb->magic = 0;
    free(rb);
}

/* Return the number of bytes currently stored. */
static size_t count(const ringbuf_t *rb) {
    if (rb->tail >= rb->head)
        return rb->tail - rb->head;
    return rb->capacity - rb->head + rb->tail;
}

size_t rb_size(const ringbuf_t *rb) {
    if (!rb)
        return 0;
    return count(rb);
}

size_t rb_capacity(const ringbuf_t *rb) {
    if (!rb)
        return 0;
    return rb->capacity;
}

/* Write `len` bytes from `data` into the buffer. Returns bytes actually written. */
size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len) {
    if (!rb || !data)
        return 0;

    size_t free_space = rb->capacity - count(rb);
    if (free_space == 0 || len == 0)
        return 0;

    /* Cap write to available space */
    size_t n = len < free_space ? len : free_space;

    const uint8_t *p = data;
    size_t remaining = n;

    /* First chunk: from tail to end of buffer (wrapping portion) */
    if (rb->tail >= rb->head) {
        /* Contiguous section before wrap */
        size_t first = rb->capacity - rb->tail;
        if (remaining <= first) {
            __builtin_memcpy(rb->buf + rb->tail, p, remaining);
            rb->tail += remaining;
            return n;
        }
        memcpy(rb->buf + rb->tail, p, first);
        rb->tail = 0;
        p += first;
        remaining -= first;
    }

    /* Second chunk: from head onward */
    if (remaining > 0) {
        size_t second = rb->capacity - rb->head;
        if (remaining >= second) {
            memcpy(rb->buf + rb->head, p, second);
            rb->tail = rb->head;                /* buffer full now */
        } else {
            memcpy(rb->buf + rb->head, p, remaining);
            rb->tail = rb->head + remaining;
        }
    }

    return n;
}

/* Read `len` bytes from the oldest end. Returns bytes actually read. */
size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out)
        return 0;

    size_t sz = count(rb);
    if (sz == 0 || len == 0)
        return 0;

    size_t n = len < sz ? len : sz;

    const uint8_t *p = out;
    size_t remaining = n;

    if (rb->head <= rb->tail) {
        /* Contiguous data region */
        size_t first = rb->tail - rb->head;
        if (remaining <= first) {
            memcpy((uint8_t *)out, rb->buf + rb->head, remaining);
            rb->head += remaining;
            return n;
        }
        memcpy(out, rb->buf + rb->head, first);
        out = ((uint8_t *)out) + first;
        rb->head = 0;
        remaining -= first;
    }

    /* Read from head (wrapped portion) */
    if (remaining > 0) {
        size_t second = rb->capacity - rb->head;
        if (remaining >= second) {
            memcpy(out, rb->buf + rb->head, second);
            remaining -= second;
        } else {
            memcpy(out, rb->buf + rb->head, remaining);
            rb->head += remaining;
            remaining = 0;
        }
    }

    /* If the buffer is empty after reading, reset both pointers */
    if (count(rb) == 0)
        rb->head = rb->tail = 0;

    return n;
}

/* Copy up to `len` oldest bytes into `out` without removing them. */
size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out)
        return 0;

    size_t sz = count(rb);
    if (sz == 0 || len == 0)
        return 0;

    size_t n = len < sz ? len : sz;

    /* Copy the contiguous range [head, head+n) modulo capacity */
    for (size_t i = 0; i < n; ++i)
        out[i] = rb->buf[(rb->head + i) % rb->capacity];

    return n;
}

void rb_clear(ringbuf_t *rb) {
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
}

#include <assert.h>
#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

int main(void) {
    /* 1. Create / destroy basic */
    ringbuf_t *rb = rb_create(8);
    assert(rb != NULL);
    assert(rb_size(rb) == 0);
    assert(rb_capacity(rb) == 8);

    /* 2. Write and read single bytes */
    uint8_t w[] = {1, 2, 3};
    size_t wrote = rb_write(rb, w, sizeof(w));
    assert(wrote == 3);
    assert(rb_size(rb) == 3);

    uint8_t r[3] = {0};
    size_t rd = rb_read(rb, r, sizeof(r));
    assert(rd == 3);
    assert(memcmp(r, w, 3) == 0);
    assert(rb_size(rb) == 0);

    /* 3. Wrap-around: fill past the boundary */
    uint8_t w2[] = {10,11,12,13,14,15,16,17};       /* exactly capacity = 8 */
    rb_write(rb, w2, sizeof(w2));                      /* fill it */
    assert(rb_size(rb) == 8);

    uint8_t r2[4];
    rb_read(rb, r2, 4);                               /* read first half */
    assert(rb_size(rb) == 4);
    for (int i = 0; i < 4; ++i)
        assert(r2[i] == w2[i]);

    /* write more – should wrap */
    uint8_t w3[] = {20, 21, 22, 23};
    rb_write(rb, w3, sizeof(w3));
    uint8_t r3[4];
    rb_read(rb, r3, 4);                               /* should get the new tail wrapped data */
    assert(memcmp(r3, w3, 4) == 0);

    /* 4. Partial write (fill exactly to capacity) */
    ringbuf_t *rb4 = rb_create(4);
    uint8_t a[] = {1,2};
    rb_write(rb4, a, sizeof(a));
    assert(rb_size(rb4) == 2);
    size_t n = rb_write(rb4, a, sizeof(a));            /* should write exactly 2 more */
    assert(n == 2);
    assert(rb_size(rb4) == 4);                          /* now full */

    /* 5. Write when full returns 0 */
    n = rb_write(rb4, a, sizeof(a));
    assert(n == 0);

    /* 6. Peek */
    uint8_t peeked[2];
    size_t pn = rb_peek(rb4, peeked, 2);
    assert(pn == 2);
    assert(memcmp(peeked, a, 2) == 0);                 /* oldest bytes untouched */
    assert(rb_size(rb4) == 4);                         /* not consumed */

    /* 7. Clear */
    rb_clear(rb4);
    assert(rb_size(rb4) == 0);

    /* 8. NULL-safety */
    assert(rb_write(NULL, a, 1) == 0);
    assert(rb_read(NULL, r3, 1) == 0);
    assert(rb_peek(NULL, peeked, 1) == 0);
    assert(rb_size(NULL) == 0);
    assert(rb_capacity(NULL) == 0);
    rb_destroy(NULL);                                  /* must not crash */

    /* 9. Invalid create */
    assert(rb_create(0) == NULL);

    /* 10. Capacity-limited write stores as much as fits */
    ringbuf_t *rbsmall = rb_create(3);
    uint8_t big[] = {99,98,97,96,95};
    n = rb_write(rbsmall, big, sizeof(big));
    assert(n == 3);                                    /* only 3 bytes fit */
    uint8_t peek2[3];
    rb_peek(rbsmall, peek2, 3);
    assert(peek2[0] == 99 && peek2[1] == 98 && peek2[2] == 97);

    rb_destroy(rbsmall);
    rb_destroy(rb4);
    rb_destroy(rb);

    printf("All tests passed.\n");
    return 0;
}

