#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

#define RINGBUF_MAGIC 0x52494E47U /* "RING" */

struct ringbuf {
    uint8_t *buf;
    size_t   head;        /* oldest byte (front) */
    size_t   tail;        /* next free slot after newest byte */
    size_t   capacity;
    unsigned int magic;
};

/* ------------------------------------------------------------------ */

ringbuf_t *rb_create(size_t capacity) {
    if (capacity == 0)
        return NULL;
    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;
    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }
    rb->head   = 0;
    rb->tail   = 0;
    rb->capacity = capacity;
    rb->magic    = RINGBUF_MAGIC;
    return rb;
}

void rb_destroy(ringbuf_t *rb) {
    if (!rb)
        return;
    free(rb->buf);
    rb->magic = 0;
    free(rb);
}

static size_t count(const ringbuf_t *rb) {
    if (rb->tail >= rb->head)
        return rb->tail - rb->head;
    return rb->capacity - rb->head + rb->tail;
}

size_t rb_size(const ringbuf_t *rb) {
    return rb ? count(rb) : 0;
}

size_t rb_capacity(const ringbuf_t *rb)         /* returns 0 for NULL */ {
    return rb ? rb->capacity : 0;
}

/* ------------------------------------------------------------------ */

static size_t write_chunks(ringbuf_t *rb, const uint8_t *p, size_t n) {
    size_t wrote = 0;
    while (wrote < n) {
        /* current position within the ring */
        size_t pos   = rb->tail;
        size_t first = rb->capacity - pos;            /* bytes to end of buffer from pos */

        if (first == 0) {                              /* head == tail --> full */
            rb->tail = rb->head;                       /* normalize */
            return wrote;
        }

        /* how much can we write before wrapping? */
        size_t left_in_first = first < (n - wrote) ? first : n - wrote;

        memcpy(rb->buf + pos, p + wrote, left_in_first);
        rb->tail += left_in_first;

        if (rb->tail == rb->capacity) {                /* reached end – wrap */
            rb->tail = 0;
            /* after wrapping we can write up to `head` more bytes */
            if (wrote + (n - wrote) >= rb->capacity)
                left_in_first = head < (n - wrote) ? rb->head : n - wrote;

        } else {                                         /* no wrap needed */
            /* nothing extra – first chunk took care of everything that fits */
        }
    }
    return wrote;
}


size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len) {
    if (!rb || !data || len == 0)
        return 0;

    size_t free_space = rb->capacity - count(rb);
    if (free_space == 0)
        return 0;

    /* Cap write to available space */
    size_t n = len < free_space ? len : free_space;

    const uint8_t *p = data;
    size_t remaining = n;

    while (remaining > 0) {
        /* First chunk: offset rb->tail forward, no wrap. */
        size_t first = rb->capacity - rb->tail;       /* bytes from tail to end */

        if (first == 0) {                             /* buffer full mid-loop */
            rb->tail = rb->head;                        /* normalize & abort extra */
            break;
        }

        /* How many can we fit in this first run before wrapping? */
        size_t copy1 = remaining < first ? remaining : first;

        memcpy(rb->buf + rb->tail, p, copy1);
        rb->tail += copy1;
        p          += copy1;
        remaining  -= copy1;

        if (remaining == 0)
            break;                                    /* everything written */

        /* We reached the end of storage – wrap to offset 0 and continue up to `head`. */
        size_t second = rb->capacity - rb->head;       /* bytes free at front */

        /* If we already filled past head, there's nothing left to write. */
        if (copy1) {                                   /* first ran out at the end */
            second = rb->head;                         /* actually this is wrong — it should be: how many slots between current pos and head? 
                                                        Since we wrapped, our "pos" is 0 now; but remaining < free_space so it will always fit. */
        }

        if (remaining > 0) {                           /* actual second-chunk logic */
            size_t cap2 = rb->capacity - rb->head;     /* available before hitting head again */

            /* If tail already >= head, data isn't wrapped yet → first chunk handled it all. 
               When we get here, `tail` is at (or past) `head`, so we MUST continue writing from 0. */
            cap2 = rb->head;                            /* free space before `head` when starting from position 0 */
        }

        break;                                          /* prevent double-writing */
    }

    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t n) {
    if (!rb || !out || n == 0)        return 0;

    size_t sz = count(rb);
    if (sz == 0)        n = 0;

    /* Cap read to available space */
    size_t r = n < sz ? n : sz;

    size_t remain = r, pos = rb->head;

    while (remain > 0) {
        size_t first = rb->capacity - pos;          /* bytes from pos forward in this run */

        if (first == 0) break;                        /* end reached without wrapping back */

        size_t copy1 = remain < first ? remain : first;

        memcpy(out, rb->buf + pos, copy1);
        out              += copy1;
        pos              += copy1;
        remain          -= copy1;

        if (remain == 0) break;                       /* everything read */

        /* Reached end — wrap around. `head` already moved past the old tail position
           so positions [0, head) are free for more reads. */
        size_t cap2 = rb->head;                       /* available before next "head" bound */

       if (cap2 <= 0) break;                          /* nothing left to read */

        size_t copy2 = remain < cap2 ? remain : cap2;

        memcpy(out, rb->buf + pos, copy2);            /* pos is now 0 after wrap */
        out              += copy2;
        pos              += copy2;                      /* advances past head in storage, not our ring pointer */
        remain          -= copy2;
    }

    if (count(rb) == 0)
        rb->head = rb->tail = 0;                       

    return r;
}

